A class is a blueprint for creating objects. It encapsulates data (attributes) and functions (methods) that operate on that data. 

**Example: Designing a `BankAccount` class.**
- **Name:** BankAccount
- **Attributes (Data Members):** accountNumber, balance.
- **Visibility:** `private` for attributes (Encapsulation), `public` for methods.
- **Methods (Member Functions):** deposit(), withdraw(), displayBalance().
- **Responsibilities:** Manage funds securely and provide account info.

```cpp
#include <iostream>
using namespace std;

class BankAccount { // Class Name
private: // Visibility
    // Attributes
    int accountNumber;
    double balance;

public: // Visibility
    // Constructor (Method)
    BankAccount(int accNo, double initialBal) {
        accountNumber = accNo;
        balance = initialBal;
    }

    // Methods defining responsibilities
    void deposit(double amount) {
        if(amount > 0) balance += amount;
    }

    void withdraw(double amount) {
        if(amount > 0 && balance >= amount) balance -= amount;
        else cout << "Insufficient funds!\n";
    }

    void displayBalance() {
        cout << "Account: " << accountNumber << " | Balance: $" << balance << endl;
    }
};

int main() {
    BankAccount myAccount(101, 500.0);
    myAccount.deposit(150.0);
    myAccount.withdraw(50.0);
    myAccount.displayBalance(); // Output: Account: 101 | Balance: $600
    return 0;
}
```

```cpp
#include <iostream>
#include <string>
using namespace std;

class Book {
private:
    string title;
    string author;
    double price;

public:
    // 1. Default Constructor
    Book() {
        title = "Unknown";
        author = "Unknown";
        price = 0.0;
    }

    // 2. Parameterized Constructor
    Book(string t, string a, double p) {
        title = t;
        author = a;
        price = p;
    }

    // 3. Copy Constructor
    Book(const Book &b) {
        title = b.title;
        author = b.author;
        price = b.price;
    }

    // Method to display book info
    void display() const {
        cout << "Title: " << title << " | Author: " << author 
             << " | Price: $" << price << endl;
    }
};

int main() {
    // Using Default Constructor
    Book book1;
    cout << "Book 1 (Default): ";
    book1.display();

    // Using Parameterized Constructor
    Book book2("The C++ Programming Language", "Bjarne Stroustrup", 59.99);
    cout << "Book 2 (Parameterized): ";
    book2.display();

    // Using Copy Constructor
    Book book3 = book2;
    cout << "Book 3 (Copied from Book 2): ";
    book3.display();

    return 0;
}
```

Yes, this scenario uses **Hierarchical Inheritance** because multiple derived classes (`Rectangle` and `Circle`) inherit from a single common base class (`Shape`).

```cpp
#include <iostream>
using namespace std;

class Shape { // Base Class
public:
    virtual void getdata() = 0; 
    virtual void printdata() = 0;
    virtual float area() = 0;
};

class Rectangle : public Shape { // Derived Class 1
private:
    float length, breadth;
public:
    void getdata() override {
        cout << "Enter Length & Breadth for Rectangle: ";
        cin >> length >> breadth;
    }
    float area() override { return length * breadth; }
    void printdata() override {
        cout << "Area of Rectangle: " << area() << endl;
    }
};

class Circle : public Shape { // Derived Class 2
private:
    float radius;
public:
    void getdata() override {
        cout << "Enter Radius for Circle: ";
        cin >> radius;
    }
    float area() override { return 3.14159 * radius * radius; }
    void printdata() override {
        cout << "Area of Circle: " << area() << endl;
    }
};

int main() {
    Rectangle rect;
    rect.getdata();
    rect.printdata();

    Circle circ;
    circ.getdata();
    circ.printdata();
    return 0;
}
```
**Sample Output:**
```text
Enter Length & Breadth for Rectangle: 5 4
Area of Rectangle: 20
Enter Radius for Circle: 3
Area of Circle: 28.2743
