```cpp
#include <iostream>
using namespace std;

template <class T>
class Calculator {
private:
    T num1;
    T num2;

public:
    // Constructor
    Calculator(T n1, T n2) {
        num1 = n1;
        num2 = n2;
    }

    T addition() { return num1 + num2; }
    T subtraction() { return num1 - num2; }
    T multiplication() { return num1 * num2; }
    T division() {
        if (num2 != 0) return num1 / num2;
        else {
            cout << "Error: Division by zero! ";
            return 0;
        }
    }

    // Show function calls others
    void show() {
        cout << "Numbers: " << num1 << " and " << num2 << endl;
        cout << "Addition: " << addition() << endl;
        cout << "Subtraction: " << subtraction() << endl;
        cout << "Multiplication: " << multiplication() << endl;
        cout << "Division: " << division() << endl;
        cout << "--------------------------" << endl;
    }
};

int main() {
    // Integer Calculator
    Calculator<int> intCalc(20, 5);
    cout << "Integer Results:\n";
    intCalc.show();

    // Float Calculator
    Calculator<float> floatCalc(15.5f, 2.5f);
    cout << "Float Results:\n";
    floatCalc.show();

    return 0;
}
```

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    // 1. count(): Counts occurrences of a specific value.
    // Syntax: count(start_iterator, end_iterator, value);
    vector<int> v = {10, 20, 10, 30, 10};
    int c = count(v.begin(), v.end(), 10);
    cout << "Count of 10 is: " << c << "\n";

    // 2. sort(): Sorts elements in ascending order.
    // Syntax: sort(start_iterator, end_iterator);
    vector<int> vSort = {50, 20, 40, 10, 30};
    sort(vSort.begin(), vSort.end());
    cout << "Sorted: ";
    for(int x : vSort) cout << x << " "; 
    cout << "\n";

    // 3. merge(): Merges two sorted ranges into a new sorted range.
    // Syntax: merge(start1, end1, start2, end2, result_start);
    vector<int> v1 = {1, 3, 5}, v2 = {2, 4, 6}, v3(6);
    merge(v1.begin(), v1.end(), v2.begin(), v2.end(), v3.begin());
    cout << "Merged: ";
    for(int x : v3) cout << x << " ";
    cout << "\n";

    // 4. search(): Searches for a subsequence within a sequence.
    // Syntax: search(start1, end1, start2, end2);
    vector<int> mainVec = {1, 2, 3, 4, 5};
    vector<int> subVec = {3, 4};
    auto it = search(mainVec.begin(), mainVec.end(), subVec.begin(), subVec.end());
    if (it != mainVec.end())
        cout << "Subsequence found at index: " << distance(mainVec.begin(), it) << "\n";
    else
        cout << "Subsequence not found.\n";

    return 0;
}
```

Associative containers are optimized for rapid data retrieval based on keys. They typically use balanced binary search trees (like Red-Black trees) internally.

1.  **Set (`std::set`):** Stores unique elements in a sorted order. The value itself is the key.
2.  **Multi-set (`std::multiset`):** Like a set, but allows duplicate elements.
3.  **Map (`std::map`):** Stores key-value pairs. Keys must be unique, and elements are sorted based on the key.
4.  **Multi-map (`std::multimap`):** Like a map, but allows multiple values to have the same key.

**Example Program:**
```cpp
#include <iostream>
#include <set>
#include <map>
using namespace std;

int main() {
    // Set Example
    set<int> mySet = {30, 10, 20, 10}; // Duplicates ignored, sorted
    cout << "Set: ";
    for(int val : mySet) cout << val << " "; // Output: 10 20 30
    cout << "\n";

    // Map Example
    map<int, string> myMap;
    myMap[1] = "Apple";
    myMap[3] = "Cherry";
    myMap[2] = "Banana";
    myMap[1] = "Apricot"; // Overwrites "Apple"

    cout << "Map:\n";
    for(auto const& pair : myMap) {
        cout << pair.first << ": " << pair.second << "\n"; 
        // Output sorted by key: 1: Apricot, 2: Banana, 3: Cherry
    }
    return 0;
}
```

```cpp
#include <iostream>
#include <string>
using namespace std;

/* 1. CLASSES AND ENCAPSULATION:
   A class 'Account' encapsulates the data (accountNumber, balance)
   and the methods that operate on them. 
   Private access modifiers hide internal state to ensure security. */
class Account {
protected: // Protected so derived classes can access
    string accountNumber;
    double balance;

public:
    /* 2. CONSTRUCTORS:
       Initialize the object's state when created. */
    Account(string accNum, double initialBal) : accountNumber(accNum), balance(initialBal) {}

    // Virtual destructor for proper cleanup of derived classes
    virtual ~Account() {}

    /* 3. METHODS & ABSTRACTION:
       Methods define behavior. Virtual keyword enables Polymorphism. */
    virtual void deposit(double amount) {
        balance += amount;
        cout << "Deposited: $" << amount << ". New Balance: $" << balance << endl;
    }

    // Pure virtual function makes Account an Abstract Class
    virtual void withdraw(double amount) = 0;

    void displayBalance() const {
        cout << "Account: " << accountNumber << " | Balance: $" << balance << endl;
    }
};

/* 4. INHERITANCE:
   SavingsAccount inherits from Account, reusing its code and extending it. */
class SavingsAccount : public Account {
private:
    double interestRate;

public:
    SavingsAccount(string accNum, double initialBal, double rate)
        : Account(accNum, initialBal), interestRate(rate) {}

    /* 5. POLYMORPHISM (Method Overriding):
       Provides specific implementation for withdrawal for Savings. */
    void withdraw(double amount) override {
        if (balance - amount >= 0) {
            balance -= amount;
            cout << "Savings Withdrawal: $" << amount << endl;
        } else {
            cout << "Insufficient funds in Savings!" << endl;
        }
    }

    void applyInterest() {
        double interest = balance * (interestRate / 100);
        deposit(interest);
    }
};

class CheckingAccount : public Account {
private:
    double overdraftLimit;

public:
    CheckingAccount(string accNum, double initialBal, double limit)
        : Account(accNum, initialBal), overdraftLimit(limit) {}

    // Overriding withdraw to handle overdraft
    void withdraw(double amount) override {
        if (balance + overdraftLimit >= amount) {
            balance -= amount;
            cout << "Checking Withdrawal: $" << amount << endl;
        } else {
            cout << "Overdraft limit exceeded!" << endl;
        }
    }
};

int main() {
    /* 6. OBJECTS:
       Instantiating concrete objects of derived classes. */
    SavingsAccount savings("SA123", 1000.0, 5.0);
    CheckingAccount checking("CA456", 500.0, 200.0);

    /* POLYMORPHISM IN ACTION:
       Using base class pointers to call overridden methods. */
    Account* acc1 = &savings;
    Account* acc2 = &checking;

    cout << "--- Operations ---\n";
    acc1->deposit(200.0);
    acc1->withdraw(500.0);

    acc2->withdraw(600.0); // Uses overdraft

    return 0;
}
```
**Discussion:**
- **Robustness:** Encapsulation prevents unauthorized manipulation of account balances. 
- **Flexibility:** Inheritance allows adding new account types (e.g., `FixedDepositAccount`) without altering existing code. Polymorphism allows the system to treat all account types uniformly via base pointers, simplifying transaction processing.

**Method Overloading** allows multiple functions in the same scope to share the same name as long as their parameter lists (number or type of arguments) differ. The compiler determines which function to invoke based on the arguments provided.

*Note on part (ii): Standard C++ does not allow function overloading based solely on the return type. Functions must differ in their parameter lists. To fulfill the requirement of "different return types" while having the "same number of arguments," the types of those arguments must be different (e.g., `int` vs `double`).*

```cpp
#include <iostream>
#include <cmath>
using namespace std;

// (i) Different number of arguments with same return type (double)
// Volume of a Cube: V = side^3 (1 parameter)
double calculateVolume(double side) {
    cout << "Calculating Cube Volume...\n";
    return side * side * side;
}

// Volume of a Cylinder: V = pi * radius^2 * height (2 parameters)
double calculateVolume(double radius, double height) {
    cout << "Calculating Cylinder Volume...\n";
    return 3.14159 * radius * radius * height;
}

// (ii) Same number of arguments (1 parameter) but different argument TYPE 
// to allow overloading, and demonstrating a different return type (float).
// Volume of a Sphere: V = (4/3) * pi * radius^3
// Taking 'int' as parameter instead of 'double' to distinguish from the Cube function.
float calculateVolume(int radius) {
    cout << "Calculating Sphere Volume...\n";
    return (4.0f / 3.0f) * 3.14159f * radius * radius * radius;
}

int main() {
    double cubeSide = 5.0;
    double cylRadius = 3.0, cylHeight = 7.0;
    int sphereRadius = 4; // Using int to trigger the sphere overload

    // Calls double calculateVolume(double)
    double volCube = calculateVolume(cubeSide);
    cout << "Volume of Cube: " << volCube << "\n\n";

    // Calls double calculateVolume(double, double)
    double volCylinder = calculateVolume(cylRadius, cylHeight);
    cout << "Volume of Cylinder: " << volCylinder << "\n\n";

    // Calls float calculateVolume(int)
    float volSphere = calculateVolume(sphereRadius);
    cout << "Volume of Sphere: " << volSphere << "\n\n";

    return 0;
}
```
